using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and language." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and their impact on civilization." },
            new() { Id = 6, Code = "BIO", Name = "Biology", Description = "Study of living organisms and life processes." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, CourseCode = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses. She holds a Ph.D. from MIT and has published extensively on CS education.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 2, CourseCode = "CS201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques including divide-and-conquer, dynamic programming, and greedy algorithms.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Rodriguez", InstructorBio = "Dr. Rodriguez specializes in algorithm optimization. He previously worked at Google Research before joining academia.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 3, CourseCode = "CS301", Title = "Database Systems", Description = "Design and implementation of relational database systems. Covers SQL, normalization, indexing, transaction processing, and query optimization.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez spent a decade in industry building distributed database systems before transitioning to teaching.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false },
            new() { Id = 4, CourseCode = "CS401", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation.", Credits = 4, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses. She holds a Ph.D. from MIT and has published extensively on CS education.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new() { Id = 5, CourseCode = "MATH101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Alan Park", InstructorBio = "Dr. Park is an award-winning educator with a passion for making calculus accessible to all students.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
            new() { Id = 6, CourseCode = "MATH201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Priya Sharma", InstructorBio = "Dr. Sharma's research focuses on applied linear algebra in data science. She has authored two textbooks on the subject.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
            new() { Id = 7, CourseCode = "MATH301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:15 PM", InstructorName = "Dr. Alan Park", InstructorBio = "Dr. Park is an award-winning educator with a passion for making calculus accessible to all students.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false },
            new() { Id = 8, CourseCode = "ENG101", Title = "Composition and Rhetoric", Description = "Develop critical thinking and writing skills through essay composition, argument analysis, and research methods.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. David Kim", InstructorBio = "Prof. Kim is a published author and writing coach who emphasizes clarity and persuasion in academic writing.", DepartmentId = 3, DepartmentName = "English", IsFeatured = false },
            new() { Id = 9, CourseCode = "ENG205", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity, freedom, and social change.", Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM", InstructorName = "Dr. Angela Morrison", InstructorBio = "Dr. Morrison is a specialist in 20th-century American fiction and has received multiple teaching excellence awards.", DepartmentId = 3, DepartmentName = "English", IsFeatured = true },
            new() { Id = 10, CourseCode = "PHYS101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions for hands-on experimentation.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", InstructorName = "Dr. Robert Tanaka", InstructorBio = "Dr. Tanaka is an experimental physicist whose research in optics has been recognized internationally.", DepartmentId = 4, DepartmentName = "Physics", IsFeatured = false },
            new() { Id = 11, CourseCode = "PHYS201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:15 PM + Lab Fri 2:00–4:00 PM", InstructorName = "Dr. Robert Tanaka", InstructorBio = "Dr. Tanaka is an experimental physicist whose research in optics has been recognized internationally.", DepartmentId = 4, DepartmentName = "Physics", IsFeatured = false },
            new() { Id = 12, CourseCode = "HIST101", Title = "World Civilizations", Description = "Survey of major world civilizations from antiquity to the modern era, examining political, cultural, and economic developments.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Emily Walsh", InstructorBio = "Dr. Walsh is a historian specializing in cross-cultural exchanges along ancient trade routes.", DepartmentId = 5, DepartmentName = "History", IsFeatured = false },
            new() { Id = 13, CourseCode = "HIST250", Title = "The Modern World", Description = "Examination of global events from the Industrial Revolution to the present day, including wars, revolutions, and globalization.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Dr. Emily Walsh", InstructorBio = "Dr. Walsh is a historian specializing in cross-cultural exchanges along ancient trade routes.", DepartmentId = 5, DepartmentName = "History", IsFeatured = true },
            new() { Id = 14, CourseCode = "BIO101", Title = "Introduction to Biology", Description = "Fundamentals of cell biology, genetics, evolution, and ecology. Includes weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM + Lab Tue 1:00–3:00 PM", InstructorName = "Dr. Lisa Nguyen", InstructorBio = "Dr. Nguyen is a molecular biologist who brings her research on gene therapy into the classroom.", DepartmentId = 6, DepartmentName = "Biology", IsFeatured = false },
            new() { Id = 15, CourseCode = "BIO210", Title = "Genetics and Genomics", Description = "Principles of heredity, gene expression, genomic technologies, and applications in medicine and agriculture.", Credits = 3, Schedule = "Tue/Thu 3:30–4:45 PM", InstructorName = "Dr. Lisa Nguyen", InstructorBio = "Dr. Nguyen is a molecular biologist who brings her research on gene therapy into the classroom.", DepartmentId = 6, DepartmentName = "Biology", IsFeatured = true }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class EnrollmentService
{
    private readonly List<EnrollmentRequest> _submissions = new();

    public void Submit(EnrollmentRequest request)
    {
        _submissions.Add(request);
    }

    public List<EnrollmentRequest> GetAll() => _submissions.ToList();
}

