@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService
@inject NavigationManager Navigation
@rendermode InteractiveServer

<PageTitle>Course Catalog - Browse Courses</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Browse Courses</h1>

    <div class="row g-3 mb-4">
        <div class="col-md-6">
            <input type="text" class="form-control" placeholder="Search by title, code, or instructor..."
                   @bind="SearchTerm" @bind:event="oninput" @bind:after="ApplyFilters" />
        </div>
        <div class="col-md-4">
            <select class="form-select" @bind="SelectedDepartmentId" @bind:after="ApplyFilters">
                <option value="0">All Departments</option>
                @foreach (var dept in _departments)
                {
                    <option value="@dept.Id">@dept.Name</option>
                }
            </select>
        </div>
        <div class="col-md-2">
            <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear</button>
        </div>
    </div>

    <p class="text-muted">Showing @_courses.Count course(s)</p>

    <div class="row g-3">
        @foreach (var course in _courses)
        {
            <div class="col-md-6 col-lg-4">
                <div class="card h-100">
                    <div class="card-body">
                        <span class="badge bg-secondary mb-2">@course.CourseCode</span>
                        @if (course.IsFeatured)
                        {
                            <span class="badge bg-warning text-dark mb-2">Featured</span>
                        }
                        <h5 class="card-title">@course.Title</h5>
                        <p class="card-text text-muted small mb-1">@course.DepartmentName</p>
                        <p class="card-text small">@course.Credits credits &bull; @course.InstructorName</p>
                        <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>

    @if (_courses.Count == 0)
    {
        <div class="alert alert-info mt-3">No courses match your search criteria.</div>
    }
</div>

@code {
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private string SearchTerm { get; set; } = string.Empty;
    private int SelectedDepartmentId { get; set; }
    private List<Course> _courses = new();
    private List<Department> _departments = new();

    protected override void OnInitialized()
    {
        _departments = CatalogService.GetDepartments();
        if (DepartmentId.HasValue)
            SelectedDepartmentId = DepartmentId.Value;
        ApplyFilters();
    }

    private void ApplyFilters()
    {
        _courses = CatalogService.SearchCourses(SearchTerm, SelectedDepartmentId > 0 ? SelectedDepartmentId : null);
    }

    private void ClearFilters()
    {
        SearchTerm = string.Empty;
        SelectedDepartmentId = 0;
        ApplyFilters();
    }
}

