@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService
@inject EnrollmentService EnrollmentService
@inject NavigationManager Navigation
@rendermode InteractiveServer

<PageTitle>Enrollment Request - Course Catalog</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Enrollment Request</h1>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <h4>Request Submitted!</h4>
            <p>Your enrollment request has been received. You will be notified once it is processed.</p>
        </div>
        <a href="/courses" class="btn btn-primary">Browse More Courses</a>
    }
    else
    {
        <div class="row">
            <div class="col-lg-8">
                <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                    <DataAnnotationsValidator />
                    <ValidationSummary class="text-danger mb-3" />

                    <div class="mb-3">
                        <label for="studentName" class="form-label">Full Name</label>
                        <InputText id="studentName" class="form-control" @bind-Value="_model.StudentName" />
                        <ValidationMessage For="() => _model.StudentName" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID</label>
                        <InputText id="studentId" class="form-control" @bind-Value="_model.StudentId" />
                        <small class="form-text text-muted">6-10 alphanumeric characters (e.g., STU12345)</small>
                        <ValidationMessage For="() => _model.StudentId" class="text-danger" />
                    </div>

                    <div class="mb-3">
                        <label for="courseSelect" class="form-label">Course</label>
                        <InputSelect id="courseSelect" class="form-select" @bind-Value="_model.CourseId">
                            <option value="0">-- Select a course --</option>
                            @foreach (var course in _courses)
                            {
                                <option value="@course.Id">@course.CourseCode - @course.Title</option>
                            }
                        </InputSelect>
                        <ValidationMessage For="() => _model.CourseId" class="text-danger" />
                    </div>

                    <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                    <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
                </EditForm>
            </div>
        </div>
    }
</div>

@code {
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private EnrollmentRequest _model = new();
    private List<Course> _courses = new();
    private bool _submitted;

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetAllCourses();
        if (CourseId.HasValue)
            _model.CourseId = CourseId.Value;
    }

    private void HandleSubmit()
    {
        EnrollmentService.Submit(_model);
        _submitted = true;
    }
}

